```python
def fibonacci(n): if n <= 0: return [] elif n == 1: return [0] elif n == 2: return [0, 1] else: prev, curr = 0, 1 fib_sequence = [0, 1] for _ in range(2, n): prev, curr = curr, prev + curr fib_sequence.append(curr) return fib_sequence # Ví dụ: in số Fibonacci thứ 10 print(fibonacci(10))
``
